script:
// Initialize dates
let today = frappe.datetime.get_today();
let todayDate = frappe.datetime.str_to_obj(today);
let year = todayDate.getFullYear();
let month = todayDate.getMonth();

let monthStart = new Date(year, month, 1);
let monthEnd = new Date(year, month + 1, 0);

function toISODate(date) {
    return date.toISOString().split('T')[0];
}

let currentRange = { first_day: toISODate(monthStart), last_day: toISODate(monthEnd) };

// Create Frappe date controls
let fromDateControl = frappe.ui.form.make_control({
    parent: root_element.querySelector('#quotation-from-date-wrapper'),
    df: { fieldtype: 'Date', fieldname: 'from_date', placeholder: 'From Date' },
    render_input: true
});
fromDateControl.set_value(toISODate(monthStart));

let toDateControl = frappe.ui.form.make_control({
    parent: root_element.querySelector('#quotation-to-date-wrapper'),
    df: { fieldtype: 'Date', fieldname: 'to_date', placeholder: 'To Date' },
    render_input: true
});
toDateControl.set_value(toISODate(monthEnd));// Populate quarter options
let quarterSelect = root_element.querySelector('#quotation-quarter-select');
let quarters = [];
for (let y = year; y >= year - 2; y--) {
    for (let q = 4; q >= 1; q--) {
        if (y === year && q > Math.floor(month / 3) + 1) continue;
        quarters.push({ year: y, quarter: q });
    }
}
quarters.slice(0, 8).forEach(function(item, idx) {
    let opt = document.createElement('option');
    opt.value = item.year + '-Q' + item.quarter;
    opt.textContent = 'Q' + item.quarter + ' ' + item.year;
    if (idx === 0) opt.selected = true;
    quarterSelect.appendChild(opt);
});

// Ensure from_date <= to_date

    if (td && fromDateControl?.$input) {
        fromDateControl.}

    if (fd && td && fd > td) {
        toDateControl.set_value(fd);
    }
}

function fetchQuotationStats() {
    // Reset all values
    ['#quotations-total', '#quotations-in-process', '#quotations-pending'].forEach(id => {
        root_element.querySelector(id).textContent = '--';
    });
    ['#quotations-total-amount', '#quotations-in-process-amount', '#quotations-pending-amount'].forEach(id => {
        root_element.querySelector(id).textContent = '₹ --';
    });

    // Total Quotations Count
    frappe.call({
        method: 'frappe.client.get_count',
        args: { doctype: 'Quotation', filters: [['creation', '>=', currentRange.first_day], ['creation', '<=', currentRange.last_day + ' 23:59:59']] },
        callback: function(r) { if (r.message !== undefined) root_element.querySelector('#quotations-total').textContent = r.message; }
    });

    // In Process Count
    frappe.call({
        method: 'frappe.client.get_count',
        args: { doctype: 'Quotation', filters: [['creation', '>=', currentRange.first_day], ['creation', '<=', currentRange.last_day + ' 23:59:59'], ['status', 'in', ['Replied', 'Partially Ordered']]] },
        callback: function(r) { if (r.message !== undefined) root_element.querySelector('#quotations-in-process').textContent = r.message; }
    });

    // Pending Count
    frappe.call({
        method: 'frappe.client.get_count',
        args: { doctype: 'Quotation', filters: [['creation', '>=', currentRange.first_day], ['creation', '<=', currentRange.last_day + ' 23:59:59'], ['status', '=', 'Open']] },
        callback: function(r) { if (r.message !== undefined) root_element.querySelector('#quotations-pending').textContent = r.message; }
    });

    // All 3 Net Totals
    fetchNetTotal([
        ['creation', '>=', currentRange.first_day],
        ['creation', '<=', currentRange.last_day + ' 23:59:59']
    ], '#quotations-total-amount');

    fetchNetTotal([
        ['creation', '>=', currentRange.first_day],
        ['creation', '<=', currentRange.last_day + ' 23:59:59'],
        ['status', 'in', ['Replied', 'Partially Ordered']]
    ], '#quotations-in-process-amount');

    fetchNetTotal([
        ['creation', '>=', currentRange.first_day],
        ['creation', '<=', currentRange.last_day + ' 23:59:59'],
        ['status', '=', 'Open']
    ], '#quotations-pending-amount');
}

function fetchNetTotal(filters, target) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Quotation',
            fields: ['sum(net_total) as total'],
            filters: filters
        },
        callback: function(r) {
            let val = (r.message && r.message[0] && r.message[0].total) || 0;
            let formatted = Number(val).toLocaleString('en-IN', { 
                minimumFractionDigits: 0, 
                maximumFractionDigits: 2 
            });
            root_element.querySelector(target).textContent = '₹ ' + formatted;
        }
    });
}

fetchQuotationStats();

root_element.querySelector('#quotation-filter-type').addEventListener('change', function() {
    if (this.value === 'monthly') {
        root_element.querySelector('#quotation-monthly-filter').style.display = 'flex';
        root_element.querySelector('#quotation-quarterly-filter').style.display = 'none';
        currentRange = { first_day: fromDateControl.get_value(), last_day: toDateControl.get_value() };
    } else {
        root_element.querySelector('#quotation-monthly-filter').style.display = 'none';
        root_element.querySelector('#quotation-quarterly-filter').style.display = 'flex';
        let val = quarterSelect.value.split('-Q');
        let qYear = parseInt(val[0]), qNum = parseInt(val[1]);
        let qStart = new Date(qYear, (qNum - 1) * 3, 1);
        let qEnd = new Date(qYear, qNum * 3, 0);
        currentRange = { first_day: toISODate(qStart), last_day: toISODate(qEnd) };
    fetchQuotationStats();
});

fromDateControl.$input.on('change', function() {
    currentRange.first_day = fromDateControl.get_value();
    fetchQuotationStats();
});
toDateControl.$input.on('change', function() {
    currentRange.last_day = toDateControl.get_value();
    fetchQuotationStats();
});

quarterSelect.addEventListener('change', function() {
    let val = this.value.split('-Q');
    let qYear = parseInt(val[0]), qNum = parseInt(val[1]);
    let qStart = new Date(qYear, (qNum - 1) * 3, 1);
    let qEnd = new Date(qYear, qNum * 3, 0);
    currentRange = { first_day: toISODate(qStart), last_day: toISODate(qEnd) };
    fetchQuotationStats();
});

root_element.querySelectorAll('.stat-card').forEach(function(card) {
    card.addEventListener('click', function() {
        let action = this.getAttribute('data-action');
        let filters = { 'creation': ['between', [currentRange.first_day, currentRange.last_day + ' 23:59:59']] };
        if (action === 'in-process') filters['status'] = ['in', ['Replied', 'Partially Ordered']];
        else if (action === 'pending') filters['status'] = 'Open';
        frappe.set_route('List', 'Quotation', filters);
    });
});

