    root_element.querySelector('#customers-total').textContent = '--';

    frappe.call({
        method: 'frappe.client.get_count',
        args: { doctype: 'Customer', filters: [['creation', '>=', currentRange.first_day], ['creation', '<=', currentRange.last_day + ' 23:59:59']] },
        callback: function(r) { if (r.message !== undefined) root_element.querySelector('#customers-total').textContent = r.message; }
