        let val = quarterSelect.value.split('-Q');
        let qYear = parseInt(val[0]), qNum = parseInt(val[1]);
        let qStart = new Date(qYear, (qNum - 1) * 3, 1);
        let qEnd = new Date(qYear, qNum * 3, 0);
        currentRange = { first_day: toISODate(qStart), last_day: toISODate(qEnd) };
    fetchCustomerStats();
});

fromDateControl.$input.on('change', function() {
