script:
console.log("Purchase Dashboard: Script started");

let fromDate, toDate;
const today = frappe.datetime.get_today();
const monthStart = frappe.datetime.month_start();

const fromWrapper = root_element.querySelector("#purchase-from-date");
const toWrapper = root_element.querySelector("#purchase-to-date");

if (fromWrapper && toWrapper) {
    fromDate = frappe.ui.form.make_control({
        parent: fromWrapper,
        df: { fieldtype: "Date", fieldname: "from_date", default: monthStart },
        render_input: true
    });
    fromDate.refresh();
    fromDate.set_value(monthStart);

    toDate = frappe.ui.form.make_control({
        parent: toWrapper,
        df: { fieldtype: "Date", fieldname: "to_date", default: today },
        render_input: true
    });
    toDate.refresh();
    toDate.set_value(today);

    fromDate.$input.on("change", loadAllData);
    toDate.$input.on("change", loadAllData);
}

root_element.querySelectorAll(".stat-card[data-section='po'], .stat-card[data-section='grn'], .stat-card[data-section='pi']").forEach(card => {
    card.querySelector(".card-header").addEventListener("click", () => {
        card.classList.toggle("expanded");
    });
});

root_element.addEventListener("click", (e) => {
    const action = e.target.closest("[data-action]");
    if (!action) return;
    const actionType = action.dataset.action;

    switch(actionType) {
        case "po-all":
            frappe.set_route("List", "Purchase Order", { docstatus: 1 });
            break;
        case "po-to-receive":
            frappe.set_route("List", "Purchase Order", { status: "To Receive and Bill", docstatus: 1 });
            break;
        case "po-to-bill":
            frappe.set_route("List", "Purchase Order", { status: "To Bill", docstatus: 1 });
            break;
        case "po-overdue":
            frappe.set_route("List", "Purchase Order", { status: ["in", ["To Receive and Bill", "To Bill"]], schedule_date: ["<", today], docstatus: 1 });
            break;
        case "po-completed":
            frappe.set_route("List", "Purchase Order", { status: "Completed", docstatus: 1 });
            break;
        case "grn-all":
            frappe.set_route("List", "Purchase Receipt", { docstatus: 1 });
            break;
        case "grn-to-bill":
            frappe.set_route("List", "Purchase Receipt", { status: "To Bill", docstatus: 1 });
            break;
        case "grn-completed":
            frappe.set_route("List", "Purchase Receipt", { status: "Completed", docstatus: 1 });
            break;
        case "pi-all":
            frappe.set_route("List", "Purchase Invoice", { docstatus: 1 });
            break;
        case "pi-unpaid":
            frappe.set_route("List", "Purchase Invoice", { status: "Unpaid", docstatus: 1 });
            break;
        case "pi-overdue":
            frappe.set_route("List", "Purchase Invoice", { status: "Overdue", docstatus: 1 });
            break;
        case "pi-paid":
            frappe.set_route("List", "Purchase Invoice", { status: "Paid", docstatus: 1 });
            break;
        case "supplier-link":
            const supplier = action.dataset.supplier;
            if (supplier) frappe.set_route("List", "Purchase Order", { supplier: supplier, docstatus: 1 });
            break;
    }
});

function getPreviousPeriod(fd, td) {
    const from = new Date(fd);
    const to = new Date(td);
    const diff = to - from;
    const prevTo = new Date(from.getTime() - 86400000);
    const prevFrom = new Date(prevTo.getTime() - diff);
    return { from: prevFrom.toISOString().split("T")[0], to: prevTo.toISOString().split("T")[0] };
}

function updateTrend(elementId, current, previous) {
    const el = root_element.querySelector(elementId);
    if (!el) return;
    const diff = current - previous;
    if (diff === 0 || previous === 0) { el.textContent = ""; el.className = "trend-indicator"; return; }
    const arrow = diff > 0 ? "↑" : "↓";
    const sign = diff > 0 ? "+" : "";
    el.textContent = arrow + " " + sign + diff;
    el.className = "trend-indicator " + (diff > 0 ? "trend-up" : "trend-down");
}

function showLoading() {
    root_element.querySelector(".purchase-dashboard").classList.add("loading");
    root_element.querySelectorAll(".stat-value, .sub-value, .amount, .outstanding, .expand-value, .avg-value").forEach(el => {
        el.classList.add("skeleton");
    });
}

function hideLoading() {
    root_element.querySelector(".purchase-dashboard").classList.remove("loading");
    root_element.querySelectorAll(".skeleton").forEach(el => el.classList.remove("skeleton"));
}

let compareMode = false;
root_element.querySelector("#compare-toggle")?.addEventListener("click", function() {
    compareMode = !compareMode;
    this.classList.toggle("active", compareMode);
    root_element.querySelector("#comparison-section").style.display = compareMode ? "block" : "none";
    if (compareMode) loadComparisonData();
});

function loadComparisonData() {
    const fd = fromDate?.get_value() || monthStart;
    const td = toDate?.get_value() || today;
    const prev = getPreviousPeriod(fd, td);

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#cmp-po-current").textContent = r.message || 0; checkCompareChange("po", r.message || 0); }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [prev.from, prev.to]] } },
        callback(r) { root_element.querySelector("#cmp-po-previous").textContent = r.message || 0; checkCompareChange("po", null, r.message || 0); }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) { const v = r.message?.[0]?.total || 0; root_element.querySelector("#cmp-po-amt-current").textContent = "₹ " + format_currency(v); checkCompareChange("po-amt", v); }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [prev.from, prev.to]] }, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) { const v = r.message?.[0]?.total || 0; root_element.querySelector("#cmp-po-amt-previous").textContent = "₹ " + format_currency(v); checkCompareChange("po-amt", null, v); }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Receipt", filters: { docstatus: 1, creation: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#cmp-grn-current").textContent = r.message || 0; checkCompareChange("grn", r.message || 0); }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Receipt", filters: { docstatus: 1, creation: ["between", [prev.from, prev.to]] } },
        callback(r) { root_element.querySelector("#cmp-grn-previous").textContent = r.message || 0; checkCompareChange("grn", null, r.message || 0); }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, creation: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#cmp-pi-current").textContent = r.message || 0; checkCompareChange("pi", r.message || 0); }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, creation: ["between", [prev.from, prev.to]] } },
        callback(r) { root_element.querySelector("#cmp-pi-previous").textContent = r.message || 0; checkCompareChange("pi", null, r.message || 0); }
    });
}

const compareData = {};
function checkCompareChange(key, current, previous) {
    if (current !== null) compareData[key + "-c"] = current;
    if (previous !== null) compareData[key + "-p"] = previous;
    const c = compareData[key + "-c"], p = compareData[key + "-p"];
    if (c !== undefined && p !== undefined) {
        const el = root_element.querySelector("#cmp-" + key + "-change");
        if (!el) return;
        const diff = c - p;
        const pct = p > 0 ? ((diff / p) * 100).toFixed(1) : 0;
        if (diff === 0) { el.textContent = "No change"; el.className = "compare-change neutral"; }
        else if (diff > 0) { el.textContent = "↑ +" + pct + "%"; el.className = "compare-change up"; }
        else { el.textContent = "↓ " + pct + "%"; el.className = "compare-change down"; }
    }
}

function loadAllData() {
    showLoading();
    const fd = fromDate?.get_value() || monthStart;
    const td = toDate?.get_value() || today;
    loadInquiryStats(fd, td);
    loadPOStats(fd, td);
    loadGRNStats(fd, td);
    loadPIStats(fd, td);
    loadTopSuppliers(fd, td);
    loadAverages(fd, td);
    updateRefreshTime();
    if (compareMode) loadComparisonData();
    setTimeout(hideLoading, 800);
}

function updateRefreshTime() {
    const now = new Date();
    const timeStr = now.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" });
    const el = root_element.querySelector("#last-refresh-time");
    if (el) el.textContent = timeStr;
}

root_element.querySelector("#refresh-btn")?.addEventListener("click", loadAllData);

function loadAverages(fd, td) {
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total", "count(name) as count", "sum(total_qty) as items"], limit_page_length: 0 },
        callback(r) {
            const total = r.message?.[0]?.total || 0;
            const count = r.message?.[0]?.count || 0;
            const items = r.message?.[0]?.items || 0;
            const avgVal = count > 0 ? total / count : 0;
            const avgItems = count > 0 ? (items / count).toFixed(1) : 0;
            root_element.querySelector("#avg-po-value").textContent = "₹ " + format_currency(avgVal);
            root_element.querySelector("#avg-items-per-po").textContent = avgItems;
        }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, creation: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total", "count(name) as count"], limit_page_length: 0 },
        callback(r) {
            const total = r.message?.[0]?.total || 0;
            const count = r.message?.[0]?.count || 0;
            const avgVal = count > 0 ? total / count : 0;
            root_element.querySelector("#avg-pi-value").textContent = "₹ " + format_currency(avgVal);
        }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Receipt", filters: { docstatus: 1, creation: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total", "count(name) as count"], limit_page_length: 0 },
        callback(r) {
            const total = r.message?.[0]?.total || 0;
            const count = r.message?.[0]?.count || 0;
            const avgVal = count > 0 ? total / count : 0;
            root_element.querySelector("#avg-grn-value").textContent = "₹ " + format_currency(avgVal);
        }
    });
}

function loadInquiryStats(fd, td) {
    frappe.call({
        method: "arbes_customizations.arbes_customization.override.material_request.get_inquiry_stats",
        args: { from_date: fd, to_date: td },
        callback(r) {
            if (r.message) {
                root_element.querySelector("#inquiry-total").textContent = r.message.total_inquiries || 0;
                root_element.querySelector("#inquiry-items").textContent = r.message.items_sent || 0;
                root_element.querySelector("#inquiry-pending").textContent = r.message.items_pending || 0;
            }
        }
    });
}

function loadPOStats(fd, td) {
    const prev = getPreviousPeriod(fd, td);

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [fd, td]] } },
        callback(r) {
            const current = r.message || 0;
            root_element.querySelector("#po-total").textContent = current;
            frappe.call({
                method: "frappe.client.get_count",
                args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [prev.from, prev.to]] } },
                callback(pr) { updateTrend("#po-trend", current, pr.message || 0); }
            });
        }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, status: ["in", ["To Receive and Bill", "To Bill"]], schedule_date: ["<", today] } },
        callback(r) { root_element.querySelector("#po-overdue").textContent = r.message || 0; }
    });

    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, creation: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) {
            const amt = r.message?.[0]?.total || 0;
            root_element.querySelector("#po-amount").textContent = "₹ " + format_currency(amt);
        }
    });

    ["To Receive and Bill", "To Bill", "Completed"].forEach(status => {
        frappe.call({
            method: "frappe.client.get_count",
            args: { doctype: "Purchase Order", filters: { docstatus: 1, status: status, creation: ["between", [fd, td]] } },
            callback(r) {
                const id = status === "To Receive and Bill" ? "po-to-receive" : status === "To Bill" ? "po-to-bill" : "po-completed";
                root_element.querySelector("#" + id).textContent = r.message || 0;
            }
        });
    });
}

function loadGRNStats(fd, td) {
    const prev = getPreviousPeriod(fd, td);

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Receipt", filters: { docstatus: 1, creation: ["between", [fd, td]] } },
        callback(r) {
            const current = r.message || 0;
            root_element.querySelector("#grn-total").textContent = current;
            frappe.call({
                method: "frappe.client.get_count",
                args: { doctype: "Purchase Receipt", filters: { docstatus: 1, creation: ["between", [prev.from, prev.to]] } },
                callback(pr) { updateTrend("#grn-trend", current, pr.message || 0); }
            });
        }
    });

    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Receipt", filters: { docstatus: 1, creation: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) {
            const amt = r.message?.[0]?.total || 0;
            root_element.querySelector("#grn-amount").textContent = "₹ " + format_currency(amt);
        }
    });

    ["To Bill", "Completed"].forEach(status => {
        frappe.call({
            method: "frappe.client.get_count",
            args: { doctype: "Purchase Receipt", filters: { docstatus: 1, status: status, creation: ["between", [fd, td]] } },
            callback(r) {
                const id = status === "To Bill" ? "grn-to-bill" : "grn-completed";
                root_element.querySelector("#" + id).textContent = r.message || 0;
            }
        });
    });
}

function loadPIStats(fd, td) {
    const prev = getPreviousPeriod(fd, td);

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, creation: ["between", [fd, td]] } },
        callback(r) {
            const current = r.message || 0;
            root_element.querySelector("#pi-total").textContent = current;
            frappe.call({
                method: "frappe.client.get_count",
                args: { doctype: "Purchase Invoice", filters: { docstatus: 1, creation: ["between", [prev.from, prev.to]] } },
                callback(pr) { updateTrend("#pi-trend", current, pr.message || 0); }
            });
        }
    });

    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, creation: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total", "sum(outstanding_amount) as outstanding"], limit_page_length: 0 },
        callback(r) {
            const amt = r.message?.[0]?.total || 0;
            const out = r.message?.[0]?.outstanding || 0;
            root_element.querySelector("#pi-amount").textContent = "₹ " + format_currency(amt);
            root_element.querySelector("#pi-outstanding").textContent = "Outstanding: ₹ " + format_currency(out);
        }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, status: "Unpaid", creation: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#pi-unpaid").textContent = r.message || 0; }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, status: "Overdue", creation: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#pi-overdue").textContent = r.message || 0; }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Invoice", filters: { docstatus: 1, status: "Paid", creation: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#pi-paid").textContent = r.message || 0; }
    });
}

function loadTopSuppliers(fd, td) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Purchase Order",
            filters: { docstatus: 1, creation: ["between", [fd, td]] },
            fields: ["supplier", "sum(base_grand_total) as total_amount", "count(name) as po_count"],
            group_by: "supplier",
            order_by: "total_amount desc",
            limit_page_length: 5
        },
        callback(r) {
            const body = root_element.querySelector("#top-suppliers-body");
            if (!r.message || !r.message.length) {
                body.innerHTML = '<div class="table-row empty"><span class="col-name" style="grid-column: 1/-1; text-align:center;">No data for selected period</span></div>';
                return;
            }
            let html = "";
            r.message.forEach((row, idx) => {
                html += '<div class="table-row clickable" data-action="supplier-link" data-supplier="' + row.supplier + '">';
                html += '<span class="col-rank">' + (idx + 1) + '</span>';
                html += '<span class="col-name">' + row.supplier + '</span>';
                html += '<span class="col-amount">₹ ' + format_currency(row.total_amount) + '</span>';
                html += '<span class="col-count">' + row.po_count + '</span>';
                html += '</div>';
            });
            body.innerHTML = html;
        }
    });
}

function format_currency(val) {
    if (!val) return "0";
    val = parseFloat(val);
    if (val >= 10000000) return (val / 10000000).toFixed(3) + " Cr";
    if (val >= 100000) return (val / 100000).toFixed(3) + " L";
    if (val >= 1000) return (val / 1000).toFixed(3) + " K";
    return val.toFixed(0);
}

loadAllData();

