        grid-template-columns: 1fr;
    }

    .comparison-header {
        padding-left: 0;
    }
}

script:
let fromDate, toDate;
const today = frappe.datetime.get_today();
const monthStart = frappe.datetime.month_start();
const company = frappe.defaults.get_user_default("Company");

const fromWrapper = root_element.querySelector("#basic-from-date");
const toWrapper = root_element.querySelector("#basic-to-date");

if (fromWrapper && toWrapper) {
    fromDate = frappe.ui.form.make_control({
        parent: fromWrapper,
        df: { fieldtype: "Date", fieldname: "from_date", default: monthStart },
        render_input: true
    });
    fromDate.refresh();
    fromDate.set_value(monthStart);

    toDate = frappe.ui.form.make_control({
        parent: toWrapper,
        df: { fieldtype: "Date", fieldname: "to_date", default: today },
        render_input: true
    });
    toDate.refresh();
    toDate.set_value(today);

    fromDate.$input.on("change", () => { loadData(); });
    toDate.$input.on("change", () => { loadData(); });
}

// Till Date From Filter
let tillDateFrom;
const tillDateFromWrapper = root_element.querySelector("#till-date-from");
if (tillDateFromWrapper) {
    tillDateFrom = frappe.ui.form.make_control({
        parent: tillDateFromWrapper,
        df: { fieldtype: "Date", fieldname: "till_date_from", placeholder: "From Date" },
        render_input: true
    });
    tillDateFrom.refresh();
    tillDateFrom.$input.on("change", () => { loadTillDateSummary(); });
}

root_element.querySelectorAll(".basic-card").forEach(card => {
    card.addEventListener("click", function() {
        const action = this.dataset.action;
        const fd = fromDate?.get_value() || monthStart;
        const td = toDate?.get_value() || today;

        if (action === "po-total") frappe.set_route("List", "Purchase Order", { docstatus: 1, company: company, transaction_date: ["between", [fd, td]] });
        else if (action === "po-receive") frappe.set_route("List", "Purchase Order", { docstatus: 1, company: company, per_received: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] });
        else if (action === "po-bill") frappe.set_route("List", "Purchase Order", { docstatus: 1, company: company, per_received: 100, per_billed: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] });
        else if (action === "scpo-total") frappe.set_route("List", "Purchase Order", { docstatus: 1, company: company, is_subcontracted: 1, transaction_date: ["between", [fd, td]] });
        else if (action === "scpo-receive") frappe.set_route("List", "Purchase Order", { docstatus: 1, company: company, is_subcontracted: 1, per_received: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] });
        else if (action === "scpo-bill") frappe.set_route("List", "Purchase Order", { docstatus: 1, company: company, is_subcontracted: 1, per_received: 100, per_billed: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] });
        else if (action === "mr-total") frappe.set_route("List", "Material Request", { material_request_type: "Purchase", docstatus: 1, company: company, transaction_date: ["between", [fd, td]] });
        else if (action === "mr-po") frappe.set_route("List", "Material Request", { material_request_type: "Purchase", docstatus: 1, company: company, per_ordered: [">", 0], transaction_date: ["between", [fd, td]] });
        else if (action === "mr-receive") frappe.set_route("List", "Material Request", { material_request_type: "Purchase", docstatus: 1, company: company, per_ordered: [">", 0], per_received: ["<", 100], transaction_date: ["between", [fd, td]] });
        else if (action === "mr-bill") frappe.set_route("List", "Material Request", { material_request_type: "Purchase", docstatus: 1, company: company, per_ordered: [">", 0], transaction_date: ["between", [fd, td]] });
        else if (action === "po") {
            const tillFromDate = tillDateFrom?.get_value();
            let filters = { docstatus: 1, company: company };
            if (tillFromDate) filters.transaction_date = [">=", tillFromDate];
            frappe.set_route("List", "Purchase Order", filters);
        }
        else if (action === "grn") {
            const tillFromDate = tillDateFrom?.get_value();
            let filters = { docstatus: 1, company: company };
            if (tillFromDate) filters.posting_date = [">=", tillFromDate];
            frappe.set_route("List", "Purchase Receipt", filters);
        }
        else if (action === "pi") {
            const tillFromDate = tillDateFrom?.get_value();
            let filters = { docstatus: 1, company: company };
            if (tillFromDate) filters.posting_date = [">=", tillFromDate];
            frappe.set_route("List", "Purchase Invoice", filters);
        }
    });
});

function formatNum(val) {
    if (!val) return "0";
    val = parseFloat(val);
    if (val >= 10000000) return (val / 10000000).toFixed(3) + " Cr";
    if (val >= 100000) return (val / 100000).toFixed(3) + " L";
    if (val >= 1000) return (val / 1000).toFixed(3) + " K";
    return val.toFixed(3);
}

function setAmountWithTitle(el, val) {
    if (!el) return;
    el.textContent = "Rs " + formatNum(val);
    el.title = "Rs " + parseFloat(val || 0).toLocaleString("en-IN", {maximumFractionDigits: 2});
}

function loadData() {
    const fd = fromDate?.get_value() || monthStart;
    const td = toDate?.get_value() || today;

    // ===== PURCHASE ORDERS SECTION =====
    // Total PO: Count + base_grand_total
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, company: company, transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-po-total").textContent = r.message || 0; }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, company: company, transaction_date: ["between", [fd, td]] }, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-po-total-amt"), r.message?.[0]?.total || 0); }
    });

    // To Receive/To Bill: Counts from get_count, Amounts from Report
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, company: company, per_received: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-po-receive").textContent = r.message || 0; }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, company: company, per_received: 100, per_billed: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-po-bill").textContent = r.message || 0; }
    });

    // Get To Receive/To Bill AMOUNTS from Purchase Order Analysis Report
    frappe.call({
        method: "frappe.desk.query_report.run",
        args: {
            report_name: "Purchase Order Analysis",
            filters: { company: company, from_date: fd, to_date: td, group_by_po: 1 }
        },
        callback(r) {
            const result = r.message?.result || [];
            // Last row is totals (list format)
            // Index: 11=amount, 12=billed_amount, 13=pending_amount, 14=received_qty_amount
            if (result.length > 0 && Array.isArray(result[result.length - 1])) {
                const totals = result[result.length - 1];
                const amount = parseFloat(totals[11] || 0);  // total PO amount
                const receivedAmount = parseFloat(totals[14] || 0);  // received_qty_amount
                const pendingAmount = parseFloat(totals[13] || 0);  // pending_amount = to bill
                const toReceiveAmount = amount - receivedAmount;  // to receive = amount - received
                setAmountWithTitle(root_element.querySelector("#basic-po-receive-amt"), toReceiveAmount);
                setAmountWithTitle(root_element.querySelector("#basic-po-bill-amt"), pendingAmount);
            } else {
                setAmountWithTitle(root_element.querySelector("#basic-po-receive-amt"), 0);
                setAmountWithTitle(root_element.querySelector("#basic-po-bill-amt"), 0);
            }
        }
    });

    // ===== SUBCONTRACTING PO SECTION - using same formula as report =====
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, company: company, is_subcontracted: 1, transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-scpo-total").textContent = r.message || 0; }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, company: company, is_subcontracted: 1, per_received: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-scpo-receive").textContent = r.message || 0; }
    });
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: { docstatus: 1, company: company, is_subcontracted: 1, per_received: 100, per_billed: ["<", 100], status: ["not in", ["Closed", "Stopped", "On Hold"]], transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-scpo-bill").textContent = r.message || 0; }
    });

    // Subcon amounts using custom API (same formula as Purchase Order Analysis report)
    frappe.call({
        method: "arbes_customizations.arbes_customization.api.get_subcon_po_amounts",
        args: { from_date: fd, to_date: td, company: company },
        callback(r) {
            const data = r.message || {};
            setAmountWithTitle(root_element.querySelector("#basic-scpo-total-amt"), data.total_amount || 0);
            setAmountWithTitle(root_element.querySelector("#basic-scpo-receive-amt"), data.to_receive_amount || 0);
            setAmountWithTitle(root_element.querySelector("#basic-scpo-bill-amt"), data.pending_amount || 0);
        }
    });

    // ===== MATERIAL REQUEST SECTION =====
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Material Request", filters: { docstatus: 1, company: company, material_request_type: "Purchase", transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-mr-total").textContent = r.message || 0; }
    });
    frappe.call({
        method: "arbes_customizations.arbes_customization.api.get_mr_po_amount",
        args: { from_date: fd, to_date: td, filter_type: "total" },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-mr-total-amt"), r.message || 0); }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Material Request", filters: { docstatus: 1, company: company, material_request_type: "Purchase", per_ordered: [">", 0], transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-mr-po").textContent = r.message || 0; }
    });
    frappe.call({
        method: "arbes_customizations.arbes_customization.api.get_mr_po_amount",
        args: { from_date: fd, to_date: td, filter_type: "po_issued" },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-mr-po-amt"), r.message || 0); }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Material Request", filters: { docstatus: 1, company: company, material_request_type: "Purchase", per_ordered: [">", 0], per_received: ["<", 100], status: ["not in", ["Stopped", "Cancelled"]], transaction_date: ["between", [fd, td]] } },
        callback(r) { root_element.querySelector("#basic-mr-receive").textContent = r.message || 0; }
    });
    frappe.call({
        method: "arbes_customizations.arbes_customization.api.get_mr_po_amount",
        args: { from_date: fd, to_date: td, filter_type: "to_receive" },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-mr-receive-amt"), r.message || 0); }
    });

    frappe.call({
        method: "arbes_customizations.arbes_customization.api.get_mr_to_be_billed_count",
        args: { from_date: fd, to_date: td },
        callback(r) { root_element.querySelector("#basic-mr-bill").textContent = r.message || 0; }
    });
    frappe.call({
        method: "arbes_customizations.arbes_customization.api.get_mr_po_amount",
        args: { from_date: fd, to_date: td, filter_type: "to_bill" },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-mr-bill-amt"), r.message || 0); }
    });

    // Till Date Summary is loaded separately with its own date filter
    loadTillDateSummary();
}

// ===== TILL DATE SUMMARY - separate function with from date filter =====
function loadTillDateSummary() {
    const tillFromDate = tillDateFrom?.get_value() || null;

    // Build filters - add transaction_date/posting_date only if from date is set
    let poFilters = { docstatus: 1, company: company };
    let prFilters = { docstatus: 1, company: company };
    let piFilters = { docstatus: 1, company: company };

    if (tillFromDate) {
        poFilters.transaction_date = [">=", tillFromDate];
        prFilters.posting_date = [">=", tillFromDate];
        piFilters.posting_date = [">=", tillFromDate];
    }

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Order", filters: poFilters },
        callback(r) { root_element.querySelector("#basic-po-count").textContent = r.message || 0; }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Order", filters: poFilters, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-po-amount"), r.message?.[0]?.total || 0); }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Receipt", filters: prFilters },
        callback(r) { root_element.querySelector("#basic-grn-count").textContent = r.message || 0; }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Receipt", filters: prFilters, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-grn-amount"), r.message?.[0]?.total || 0); }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Purchase Invoice", filters: piFilters },
        callback(r) { root_element.querySelector("#basic-pi-count").textContent = r.message || 0; }
    });
    frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Purchase Invoice", filters: piFilters, fields: ["sum(base_grand_total) as total"], limit_page_length: 0 },
        callback(r) { setAmountWithTitle(root_element.querySelector("#basic-pi-amount"), r.message?.[0]?.total || 0); }
    });
}

loadData();

