script:
let fromDate, toDate;
const today = frappe.datetime.get_today();
const monthStart = frappe.datetime.month_start();
const company = frappe.defaults.get_user_default("Company");

const fromWrapper = root_element.querySelector("#sales-from-date");
const toWrapper = root_element.querySelector("#sales-to-date");

if (fromWrapper && toWrapper) {
    fromDate = frappe.ui.form.make_control({
        parent: fromWrapper,
        df: { fieldtype: "Date", fieldname: "from_date", default: monthStart },
        render_input: true
    });
    fromDate.refresh();
    fromDate.set_value(monthStart);

    toDate = frappe.ui.form.make_control({
        parent: toWrapper,
        df: { fieldtype: "Date", fieldname: "to_date", default: today },
        render_input: true
    });
    toDate.refresh();
    toDate.set_value(today);

    fromDate.$input.on("change", () => { loadMonthlySummary(); loadBifurcationData(); });
    toDate.$input.on("change", () => { loadMonthlySummary(); loadBifurcationData(); });
}

// Till Date From Filter
let tillDateFrom;
const tillDateFromWrapper = root_element.querySelector("#till-date-from");
if (tillDateFromWrapper) {
    tillDateFrom = frappe.ui.form.make_control({
        parent: tillDateFromWrapper,
        df: { fieldtype: "Date", fieldname: "till_date_from", placeholder: "From Date" },
        render_input: true
    });
    tillDateFrom.refresh();
    tillDateFrom.$input.on("change", () => { loadTillDateSummary(); });
}

function formatNum(val) {
    if (!val) return "0";
    val = parseFloat(val);
    if (val >= 10000000) return (val / 10000000).toFixed(3) + " Cr";
    if (val >= 100000) return (val / 100000).toFixed(3) + " L";
    if (val >= 1000) return (val / 1000).toFixed(3) + " K";
    return val.toFixed(3);
}

function setAmountWithTitle(el, val) {
    if (!el) return;
    el.textContent = "Rs " + formatNum(val);
    el.title = "Rs " + parseFloat(val || 0).toLocaleString("en-IN", {maximumFractionDigits: 2});
}

// Till Date Summary - Uses Sales Order Analysis report for billed/pending (with from date filter)
function loadTillDateSummary() {
    const tillFromDate = tillDateFrom?.get_value() || "2000-01-01";

    // Get SO grand_total directly from Sales Orders
    let soFilters = { docstatus: 1, company: company, status: ["not in", ["Stopped", "On Hold"]] };
    if (tillFromDate && tillFromDate !== "2000-01-01") {
        soFilters.transaction_date = [">=", tillFromDate];
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Order",
            filters: soFilters,
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) {
            const soTotal = r.message?.[0]?.total || 0;
            setAmountWithTitle(root_element.querySelector("#till-so-amount"), soTotal);
        }
    });

    // Get billed/pending from Sales Order Analysis report
    frappe.call({
        method: "frappe.desk.query_report.run",
        args: {
            report_name: "Sales Order Analysis",
            filters: {
                company: company,
                from_date: tillFromDate,
                to_date: today,
                group_by_so: 1
            }
        },
        callback(r) {
            const result = r.message?.result || [];
            let billedTotal = 0, pendingTotal = 0;

            result.forEach(row => {
                if (typeof row === "object" && !Array.isArray(row)) {
                    billedTotal += row.billed_amount || 0;
                    pendingTotal += row.pending_amount || 0;
                }
            });

            setAmountWithTitle(root_element.querySelector("#till-si-amount"), billedTotal);
            setAmountWithTitle(root_element.querySelector("#till-pending-amount"), pendingTotal);
        }
    });
}

// Monthly Summary - SO grand_total from SO, billed/pending from report, SI from actual invoices
function loadMonthlySummary() {
    const fd = fromDate?.get_value() || monthStart;
    const td = toDate?.get_value() || today;

    // Get SO grand_total directly
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Order",
            filters: { 
                docstatus: 1, 
                company: company, 
                transaction_date: ["between", [fd, td]],
                status: ["not in", ["Stopped", "On Hold"]]
            },
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) {
            const soTotal = r.message?.[0]?.total || 0;
            const soEl = root_element.querySelector("#rev-so-amount");
            if (soEl) setAmountWithTitle(soEl, soTotal);
        }
    });

    // Get billed/pending from Sales Order Analysis report
    frappe.call({
