// Chart date controls
let chartFromDate, chartToDate;
const chartFromWrapper = root_element.querySelector("#chart-from-date");
const chartToWrapper = root_element.querySelector("#chart-to-date");

const sixMonthsAgo = new Date();
sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 5);
const chartDefaultFrom = frappe.datetime.obj_to_str(new Date(sixMonthsAgo.getFullYear(), sixMonthsAgo.getMonth(), 1));
const chartDefaultTo = today;

if (chartFromWrapper && chartToWrapper) {
    chartFromDate = frappe.ui.form.make_control({
        parent: chartFromWrapper,
        df: { fieldtype: "Date", fieldname: "chart_from", default: chartDefaultFrom },
        render_input: true
    });
