    chartFromDate.$input.on("change", () => { loadRevenueChart(); });
    chartToDate.$input.on("change", () => { loadRevenueChart(); });
}

// Helper to get month range
function getMonthsBetween(startDate, endDate) {
    const months = [];
    let current = new Date(startDate.getFullYear(), startDate.getMonth(), 1);
    const end = new Date(endDate.getFullYear(), endDate.getMonth(), 1);

    while (current <= end) {
        months.push({
            start: frappe.datetime.obj_to_str(current),
            end: frappe.datetime.obj_to_str(new Date(current.getFullYear(), current.getMonth() + 1, 0)),
            label: current.toLocaleDateString("en-US", { month: "short", year: "2-digit" })
        });
        current.setMonth(current.getMonth() + 1);
    }
    return months;
}

function loadRevenueChart() {
    const fromDateStr = chartFromDate?.get_value() || chartDefaultFrom;
    const toDateStr = chartToDate?.get_value() || chartDefaultTo;

    const startDate = new Date(fromDateStr);
    const endDate = new Date(toDateStr);
    const months = getMonthsBetween(startDate, endDate);

    const labels = months.map(m => m.label);
    const soData = new Array(months.length).fill(0);
    const siData = new Array(months.length).fill(0);
    const pendingData = new Array(months.length).fill(0);

    let completed = 0;
    const total = months.length * 3; // SO + SI calls per month

    function renderChart() {
        const chartEl = root_element.querySelector("#revenue-chart");
        if (chartEl && labels.length > 0) {
            chartEl.innerHTML = "";
            new frappe.Chart(chartEl, {
                type: "bar",
                height: 260,
                colors: ["#3498db", "#27ae60", "#e74c3c"],
                data: {
                    labels: labels,
                    datasets: [
                        { name: "SO (L)", values: soData },
                        { name: "SI (L)", values: siData },
                        { name: "Pending (L)", values: pendingData }
                    ]
                },
                barOptions: { spaceRatio: 0.3 },
                tooltipOptions: { formatTooltipY: d => d.toFixed(3) + " L" }
            });
        }
    }

    months.forEach((month, idx) => {
        // Get SO grand_total directly
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Sales Order",
                filters: {
                    docstatus: 1,
                    company: company,
                    transaction_date: ["between", [month.start, month.end]],
                    status: ["not in", ["Stopped", "On Hold"]]
                },
                fields: ["sum(base_grand_total) as total"],
                limit_page_length: 0
            },
            callback(r) {
                const soTotal = r.message?.[0]?.total || 0;
                soData[idx] = Math.round(soTotal / 100000 * 100) / 100;
                completed++;
                if (completed === total) renderChart();
            }
        });

        // Get pending from report
        frappe.call({
            method: "frappe.desk.query_report.run",
            args: {
                report_name: "Sales Order Analysis",
                filters: {
                    company: company,
                    from_date: month.start,
                    to_date: month.end,
                    group_by_so: 1
                }
            },
            callback(r) {
                const result = r.message?.result || [];
                let pendingTotal = 0;

                result.forEach(row => {
                    if (typeof row === "object" && !Array.isArray(row)) {
                        pendingTotal += row.pending_amount || 0;
                    }
                });

                pendingData[idx] = Math.round(pendingTotal / 100000 * 100) / 100;
                completed++;
                if (completed === total) renderChart();
            }
        });

        // Get SI data
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Sales Invoice",
                filters: {
                    docstatus: 1,
                    company: company,
                    posting_date: ["between", [month.start, month.end]]
                },
                fields: ["sum(base_grand_total) as total"],
                limit_page_length: 0
            },
            callback(r) {
                const siTotal = r.message?.[0]?.total || 0;
                siData[idx] = Math.round(siTotal / 100000 * 100) / 100;
                completed++;
                if (completed === total) renderChart();
            }
        });
    });
}

// Load Bifurcation Data (Domestic/Export)
function loadBifurcationData() {
    const fd = fromDate?.get_value() || monthStart;
    const td = toDate?.get_value() || today;

    // Domestic - Booked
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Order",
            filters: { docstatus: 1, company: company, transaction_date: ["between", [fd, td]], status: ["not in", ["Stopped", "On Hold"]], custom_domestic_export: "Domestic" },
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) { setAmountWithTitle(root_element.querySelector("#domestic-booked"), r.message?.[0]?.total || 0); }
    });

    // Domestic - Billed (from SI linked to SO)
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Invoice",
            filters: { docstatus: 1, company: company, posting_date: ["between", [fd, td]], custom_domestic_export: "Domestic" },
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) { setAmountWithTitle(root_element.querySelector("#domestic-billed"), r.message?.[0]?.total || 0); }
    });

    // All Pending - from custom API (uses same item-level formula as SO Analysis report: base_amount - billed_amt)
    frappe.call({
        method: "arbes_customizations.arbes_customization.api.get_sales_bifurcation_pending",
        args: { from_date: fd, to_date: td, company: company },
        callback(r) {
            if (r.message) {
                setAmountWithTitle(root_element.querySelector("#domestic-pending"), r.message.domestic_pending || 0);
                setAmountWithTitle(root_element.querySelector("#export-usa-pending"), r.message.export_usa_pending || 0);
                setAmountWithTitle(root_element.querySelector("#export-row-pending"), r.message.export_row_pending || 0);
            }
        }
    });

    // Export USA - Booked
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Order",
            filters: { docstatus: 1, company: company, transaction_date: ["between", [fd, td]], status: ["not in", ["Stopped", "On Hold"]], custom_domestic_export: "Export", territory: "USA" },
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) { setAmountWithTitle(root_element.querySelector("#export-usa-booked"), r.message?.[0]?.total || 0); }
    });

    // Export USA - Billed
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Invoice",
            filters: { docstatus: 1, company: company, posting_date: ["between", [fd, td]], custom_domestic_export: "Export", territory: "USA" },
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) { setAmountWithTitle(root_element.querySelector("#export-usa-billed"), r.message?.[0]?.total || 0); }
    });

    // Export Rest of World - Booked
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Order",
            filters: { docstatus: 1, company: company, transaction_date: ["between", [fd, td]], status: ["not in", ["Stopped", "On Hold"]], custom_domestic_export: "Export", territory: ["!=", "USA"] },
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) { setAmountWithTitle(root_element.querySelector("#export-row-booked"), r.message?.[0]?.total || 0); }
    });

    // Export Rest of World - Billed
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Sales Invoice",
            filters: { docstatus: 1, company: company, posting_date: ["between", [fd, td]], custom_domestic_export: "Export", territory: ["!=", "USA"] },
            fields: ["sum(base_grand_total) as total"],
            limit_page_length: 0
        },
        callback(r) { setAmountWithTitle(root_element.querySelector("#export-row-billed"), r.message?.[0]?.total || 0); }
    });
}

// Setup click handlers for redirections
function setupClickHandlers() {
    const fd = () => fromDate?.get_value() || monthStart;
    const td = () => toDate?.get_value() || today;
    const tillFd = () => tillDateFrom?.get_value() || null;

    // Till Date cards click handlers
    root_element.querySelectorAll(".till-card[data-action]").forEach(card => {
        card.addEventListener("click", () => {
            const action = card.dataset.action;
            const fromDate = tillFd();

            if (action === "till-so") {
                let filters = { docstatus: 1, company: company, status: ["not in", ["Stopped", "On Hold"]] };
                if (fromDate) filters.transaction_date = [">=", fromDate];
                frappe.set_route("List", "Sales Order", filters);
            } else if (action === "till-si") {
                let filters = { docstatus: 1, company: company };
                if (fromDate) filters.posting_date = [">=", fromDate];
                frappe.set_route("List", "Sales Invoice", filters);
            } else if (action === "till-pending") {
                let filters = { docstatus: 1, company: company, per_billed: ["<", 100], status: ["not in", ["Stopped", "On Hold", "Closed"]] };
                if (fromDate) filters.transaction_date = [">=", fromDate];
                frappe.set_route("List", "Sales Order", filters);
            }
        });
    });

    // Helper to add click handler
    function addClickHandler(selector, doctype, getFilters) {
        const el = root_element.querySelector(selector);
        if (el) {
            const card = el.closest(".bif-card") || el.closest(".revenue-card");
            if (card) {
                card.style.cursor = "pointer";
                card.addEventListener("click", () => {
                    frappe.set_route("List", doctype, getFilters());
                });
            }
        }
    }

    // Domestic cards
    addClickHandler("#domestic-booked", "Sales Order", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Domestic",
        transaction_date: ["between", [fd(), td()]], status: ["not in", ["Stopped", "On Hold"]]
    }));
    addClickHandler("#domestic-billed", "Sales Invoice", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Domestic",
        posting_date: ["between", [fd(), td()]]
    }));
    addClickHandler("#domestic-pending", "Sales Order", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Domestic",
        transaction_date: ["between", [fd(), td()]], per_billed: ["<", 100], status: ["not in", ["Stopped", "On Hold", "Closed"]]
    }));

    // Export USA cards
    addClickHandler("#export-usa-booked", "Sales Order", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Export", territory: "USA",
        transaction_date: ["between", [fd(), td()]], status: ["not in", ["Stopped", "On Hold"]]
    }));
    addClickHandler("#export-usa-billed", "Sales Invoice", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Export", territory: "USA",
        posting_date: ["between", [fd(), td()]]
    }));
    addClickHandler("#export-usa-pending", "Sales Order", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Export", territory: "USA",
        transaction_date: ["between", [fd(), td()]], per_billed: ["<", 100], status: ["not in", ["Stopped", "On Hold", "Closed"]]
    }));

    // Export ROW cards
    addClickHandler("#export-row-booked", "Sales Order", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Export", territory: ["!=", "USA"],
        transaction_date: ["between", [fd(), td()]], status: ["not in", ["Stopped", "On Hold"]]
    }));
    addClickHandler("#export-row-billed", "Sales Invoice", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Export", territory: ["!=", "USA"],
        posting_date: ["between", [fd(), td()]]
    }));
    addClickHandler("#export-row-pending", "Sales Order", () => ({
        docstatus: 1, company: company, custom_domestic_export: "Export", territory: ["!=", "USA"],
        transaction_date: ["between", [fd(), td()]], per_billed: ["<", 100], status: ["not in", ["Stopped", "On Hold", "Closed"]]
    }));

    // Monthly summary cards
    addClickHandler("#rev-so-amount", "Sales Order", () => ({
        docstatus: 1, company: company, transaction_date: ["between", [fd(), td()]], status: ["not in", ["Stopped", "On Hold"]]
    }));
    addClickHandler("#rev-si-amount", "Sales Invoice", () => ({
        docstatus: 1, company: company, posting_date: ["between", [fd(), td()]]
    }));
    addClickHandler("#rev-pending-amount", "Sales Order", () => ({
        docstatus: 1, company: company, transaction_date: ["between", [fd(), td()]], per_billed: ["<", 100], status: ["not in", ["Stopped", "On Hold", "Closed"]]
    }));
}

