script:
const today = frappe.datetime.get_today();
const monthStart = frappe.datetime.month_start();
const monthEnd = frappe.datetime.month_end();

// Global Issue Type filter
let issueTypeFilter;
const issueTypeWrapper = root_element.querySelector("#issue-type-filter");
if (issueTypeWrapper) {
    issueTypeFilter = frappe.ui.form.make_control({
        parent: issueTypeWrapper,
        df: { fieldtype: "Link", fieldname: "issue_type", options: "Issue Type", placeholder: "All Types", change: () => { setTimeout(refreshAllData, 100); } },
        render_input: true
    });
    issueTypeFilter.refresh();
    issueTypeFilter.$input.on("awesomplete-selectcomplete", () => { refreshAllData(); });
    issueTypeFilter.$input.on("keydown keyup keypress", (e) => { e.stopPropagation(); });
}

function getIssueTypeFilter() {
    const val = issueTypeFilter?.get_value();
    return val ? { issue_type: val } : {};
}

function refreshAllData() {
    loadTillDateData();
    loadRangeData();
    loadResponseChart();
    loadAgeingData();
}

// Till Date filter
let tillFromDate;
const tillFromWrapper = root_element.querySelector("#support-from-date");
if (tillFromWrapper) {
    tillFromDate = frappe.ui.form.make_control({
        parent: tillFromWrapper,
        df: { fieldtype: "Date", fieldname: "till_from_date", default: "2000-01-01" },
        render_input: true
    });
    tillFromDate.refresh();
    tillFromDate.set_value("2000-01-01");
    tillFromDate.$input.on("change", () => { loadTillDateData(); });
}

// Date Range Summary filters
let rangeFromDate, rangeToDate;
const rangeFromWrapper = root_element.querySelector("#range-from-date");
const rangeToWrapper = root_element.querySelector("#range-to-date");

if (rangeFromWrapper) {
    rangeFromDate = frappe.ui.form.make_control({
        parent: rangeFromWrapper,
        df: { fieldtype: "Date", fieldname: "range_from_date" },
        render_input: true
    });
    rangeFromDate.refresh();
    rangeFromDate.set_value(monthStart);
    rangeFromDate.$input.on("change", () => { loadRangeData(); });
}

if (rangeToWrapper) {
    rangeToDate = frappe.ui.form.make_control({
        parent: rangeToWrapper,
        df: { fieldtype: "Date", fieldname: "range_to_date" },
        render_input: true
    });
    rangeToDate.refresh();
    rangeToDate.set_value(monthEnd);
    rangeToDate.$input.on("change", () => { loadRangeData(); });
}

// Chart filters
let chartFromDate, chartToDate;
const chartFromWrapper = root_element.querySelector("#chart-from-date");
const chartToWrapper = root_element.querySelector("#chart-to-date");

if (chartFromWrapper) {
    chartFromDate = frappe.ui.form.make_control({
        parent: chartFromWrapper,
        df: { fieldtype: "Date", fieldname: "chart_from_date" },
        render_input: true
    });
    chartFromDate.refresh();
    chartFromDate.set_value(monthStart);
    chartFromDate.$input.on("change", () => { loadResponseChart(); });
}

if (chartToWrapper) {
    chartToDate = frappe.ui.form.make_control({
        parent: chartToWrapper,
        df: { fieldtype: "Date", fieldname: "chart_to_date" },
        render_input: true
    });
    chartToDate.refresh();
    chartToDate.set_value(monthEnd);
    chartToDate.$input.on("change", () => { loadResponseChart(); });
}

// Till Date Data
function loadTillDateData() {
    const fd = tillFromDate?.get_value() || "2000-01-01";
    const itf = getIssueTypeFilter();

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: [">=", fd], ...itf } },
        callback(r) {
            root_element.querySelector("#till-total").textContent = r.message || 0;
        }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: [">=", fd], status: ["not in", ["Closed", "Resolved"]], ...itf } },
        callback(r) {
            root_element.querySelector("#till-open").textContent = r.message || 0;
        }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: [">=", fd], status: ["in", ["Closed", "Resolved"]], ...itf } },
        callback(r) {
            root_element.querySelector("#till-closed").textContent = r.message || 0;
        }
    });
}

// Date Range Summary Data
function loadRangeData() {
    const fd = rangeFromDate?.get_value() || monthStart;
    const td = rangeToDate?.get_value() || monthEnd;
    const itf = getIssueTypeFilter();

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: ["between", [fd, td + " 23:59:59"]], ...itf } },
        callback(r) {
            root_element.querySelector("#month-total").textContent = r.message || 0;
        }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: ["between", [fd, td + " 23:59:59"]], status: ["not in", ["Closed", "Resolved"]], ...itf } },
        callback(r) {
            root_element.querySelector("#month-open").textContent = r.message || 0;
        }
    });

    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { custom_closed_on: ["between", [fd, td + " 23:59:59"]], ...itf } },
        callback(r) {
            root_element.querySelector("#month-closed").textContent = r.message || 0;
        }
    });
}

// Chart: Response/Closure Times (shows all tickets - open and closed)
function loadResponseChart() {
    const fd = chartFromDate?.get_value() || monthStart;
    const td = chartToDate?.get_value() || monthEnd;
    const itf = getIssueTypeFilter();

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Issue",
            filters: { creation: ["between", [fd, td + " 23:59:59"]], ...itf },
            fields: ["name", "creation", "first_responded_on", "custom_closed_on", "status"],
            limit_page_length: 50,
            order_by: "creation desc"
        },
        callback(r) {
            const issues = r.message || [];
            const chartEl = root_element.querySelector("#response-chart");
            if (issues.length === 0) {
                chartEl.innerHTML = "<p style='text-align:center;color:#6c757d;padding:40px;'>No tickets in selected date range</p>";
                return;
            }

            const labels = [];
            const firstResponseHrs = [];
            const closureHrs = [];

            issues.forEach(issue => {
                const created = new Date(issue.creation);
                let respHrs = 0, closeHrs = 0;

                if (issue.first_responded_on) {
                    const responded = new Date(issue.first_responded_on);
                    respHrs = Math.round((responded - created) / (1000 * 60 * 60) * 10) / 10;
                }
                if (issue.custom_closed_on) {
                    const resolved = new Date(issue.custom_closed_on);
                    closeHrs = Math.round((resolved - created) / (1000 * 60 * 60) * 10) / 10;
                }

                labels.push(issue.name);
                firstResponseHrs.push(respHrs);
                closureHrs.push(closeHrs);
            });

            chartEl.innerHTML = "";
            new frappe.Chart(chartEl, {
                type: "bar",
                height: 280,
                colors: ["#3498db", "#27ae60"],
                data: {
                    labels: labels,
                    datasets: [
                        { name: "1st Response (hrs)", values: firstResponseHrs },
                        { name: "Closure (hrs)", values: closureHrs }
                    ]
                },
                barOptions: { spaceRatio: 0.3 },
                tooltipOptions: { formatTooltipY: d => d + " hrs" }
            });
        }
    });
}


// Ageing Data
function loadAgeingData() {
    const itf = getIssueTypeFilter();
    const today = new Date();
    const oneWeekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
    const twoWeeksAgo = new Date(today.getTime() - 14 * 24 * 60 * 60 * 1000);

    const formatDate = (d) => d.toISOString().split('T')[0];
    const oneWeekAgoStr = formatDate(oneWeekAgo);
    const twoWeeksAgoStr = formatDate(twoWeeksAgo);

    // < 1 Week (created within last 7 days and still open)
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: [">", oneWeekAgoStr], status: ["not in", ["Closed", "Resolved"]], ...itf } },
        callback(r) {
            root_element.querySelector("#age-week1").textContent = r.message || 0;
        }
    });

    // 1-2 Weeks (created 7-14 days ago and still open)
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: ["between", [twoWeeksAgoStr, oneWeekAgoStr]], status: ["not in", ["Closed", "Resolved"]], ...itf } },
        callback(r) {
            root_element.querySelector("#age-week2").textContent = r.message || 0;
        }
    });

    // > 2 Weeks (created more than 14 days ago and still open)
    frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Issue", filters: { creation: ["<", twoWeeksAgoStr], status: ["not in", ["Closed", "Resolved"]], ...itf } },
        callback(r) {
            root_element.querySelector("#age-old").textContent = r.message || 0;
        }
    });
}

// Click handlers for redirections
function setupClickHandlers() {
    root_element.querySelector("#till-total-card")?.addEventListener("click", () => {
        const fd = tillFromDate?.get_value() || "2000-01-01";
        const itf = getIssueTypeFilter();
        frappe.set_route("List", "Issue", { creation: [">=", fd], ...itf });
    });
    root_element.querySelector("#till-open-card")?.addEventListener("click", () => {
        const fd = tillFromDate?.get_value() || "2000-01-01";
        const itf = getIssueTypeFilter();
        frappe.set_route("List", "Issue", { creation: [">=", fd], status: ["not in", ["Closed", "Resolved"]], ...itf });
    });
    root_element.querySelector("#till-closed-card")?.addEventListener("click", () => {
        const fd = tillFromDate?.get_value() || "2000-01-01";
        const itf = getIssueTypeFilter();
        frappe.set_route("List", "Issue", { creation: [">=", fd], status: ["in", ["Closed", "Resolved"]], ...itf });
    });

    root_element.querySelector("#month-total-card")?.addEventListener("click", () => {
        const fd = rangeFromDate?.get_value() || monthStart;
        const td = rangeToDate?.get_value() || monthEnd;
        const itf = getIssueTypeFilter();
        frappe.set_route("List", "Issue", { creation: ["between", [fd, td + " 23:59:59"]], ...itf });
    });
    root_element.querySelector("#month-open-card")?.addEventListener("click", () => {
        const fd = rangeFromDate?.get_value() || monthStart;
        const td = rangeToDate?.get_value() || monthEnd;
        const itf = getIssueTypeFilter();
        frappe.set_route("List", "Issue", { creation: ["between", [fd, td + " 23:59:59"]], status: ["not in", ["Closed", "Resolved"]], ...itf });
    });
    root_element.querySelector("#month-closed-card")?.addEventListener("click", () => {
        const fd = rangeFromDate?.get_value() || monthStart;
        const td = rangeToDate?.get_value() || monthEnd;
        const itf = getIssueTypeFilter();
        frappe.set_route("List", "Issue", { custom_closed_on: ["between", [fd, td + " 23:59:59"]], ...itf });
    });
    root_element.querySelector("#age-week1-card")?.addEventListener("click", () => {
        const itf = getIssueTypeFilter();
        const oneWeekAgo = new Date(new Date().getTime() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        frappe.set_route("List", "Issue", { creation: [">", oneWeekAgo], status: ["not in", ["Closed", "Resolved"]], ...itf });
    });
    root_element.querySelector("#age-week2-card")?.addEventListener("click", () => {
        const itf = getIssueTypeFilter();
        const oneWeekAgo = new Date(new Date().getTime() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        const twoWeeksAgo = new Date(new Date().getTime() - 14 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        frappe.set_route("List", "Issue", { creation: ["between", [twoWeeksAgo, oneWeekAgo]], status: ["not in", ["Closed", "Resolved"]], ...itf });
    });
    root_element.querySelector("#age-old-card")?.addEventListener("click", () => {
        const itf = getIssueTypeFilter();
        const twoWeeksAgo = new Date(new Date().getTime() - 14 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        frappe.set_route("List", "Issue", { creation: ["<", twoWeeksAgo], status: ["not in", ["Closed", "Resolved"]], ...itf });
    });
}

// Initial load
loadTillDateData();
loadRangeData();
loadResponseChart();
loadAgeingData();
setupClickHandlers();

